import json, sys, time, urllib.request, urllib.error

BASE = "http://localhost:8080"
LOG = open("/tmp/recon/events.log", "w")

def log(msg):
    LOG.write(msg + "\n"); LOG.flush()

state = {"token": None}

def get_token():
    req = urllib.request.Request(BASE + "/token", method="POST")
    with urllib.request.urlopen(req, timeout=30) as r:
        state["token"] = json.load(r)["token"]
    log(f"token issued {state['token']}")

def request(path, auth=True, max_attempts=200):
    attempt = 0
    while True:
        attempt += 1
        if attempt > max_attempts:
            raise RuntimeError(f"gave up on {path} after {max_attempts} attempts")
        headers = {}
        if auth:
            if state["token"] is None:
                get_token()
            headers["Authorization"] = "Bearer " + state["token"]
        req = urllib.request.Request(BASE + path, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                body = r.read().decode()
                return r.status, json.loads(body)
        except urllib.error.HTTPError as e:
            body = e.read().decode(errors="replace")
            ra = e.headers.get("Retry-After")
            log(f"{path} attempt {attempt}: HTTP {e.code} retry-after={ra} body={body[:300]}")
            if e.code == 401 or e.code == 403:
                get_token()
                continue
            if e.code == 429:
                wait = float(ra) if ra is not None else 1.0
                time.sleep(wait)
                continue
            if e.code == 404:
                return 404, body
            if e.code >= 500:
                time.sleep(min(2 ** min(attempt, 5) * 0.2, 10))
                continue
            raise RuntimeError(f"unexpected HTTP {e.code} on {path}: {body[:300]}")
        except (urllib.error.URLError, TimeoutError, ConnectionError, json.JSONDecodeError) as e:
            log(f"{path} attempt {attempt}: transport/parse error {e!r}")
            time.sleep(min(2 ** min(attempt, 5) * 0.2, 10))
            continue

def main():
    orders_pages = []
    path = "/orders?page=1"
    page_no = 1
    while path is not None:
        status, data = request(path)
        if status != 200:
            raise RuntimeError(f"orders page failed: {status} {data}")
        orders_pages.append({"path": path, "page": data["page"], "total_pages": data["total_pages"],
                             "next": data["next"], "count": len(data["items"]), "items": data["items"]})
        log(f"page {data['page']}/{data['total_pages']} items={len(data['items'])} next={data['next']}")
        path = data["next"]
    json.dump(orders_pages, open("/tmp/recon/orders_pages.json", "w"))

    cust_ids = sorted({o["customer_id"] for p in orders_pages for o in p["items"]})
    customers = {}
    for cid in cust_ids:
        status, data = request(f"/customers/{cid}")
        if status == 200:
            customers[cid] = data
        else:
            customers[cid] = {"missing": True, "body": data}
            log(f"customer {cid} status {status}")
    json.dump(customers, open("/tmp/recon/customers.json", "w"))
    log(f"done: pages={len(orders_pages)} customers={len(customers)}")

if __name__ == "__main__":
    main()
